-- Verificacion de cargas
SELECT 'participants' AS table_name, COUNT(*) AS rows FROM participants
UNION ALL SELECT 'match_results', COUNT(*) FROM match_results
UNION ALL SELECT 'predictions', COUNT(*) FROM predictions
UNION ALL SELECT 'group_predictions', COUNT(*) FROM group_predictions
UNION ALL SELECT 'individual_predictions', COUNT(*) FROM individual_predictions
UNION ALL SELECT 'top_scorers_cache', COUNT(*) FROM top_scorers_cache
UNION ALL SELECT 'scores_cache', COUNT(*) FROM scores_cache;

SELECT stage, COUNT(*) AS prediction_rows FROM predictions GROUP BY stage ORDER BY stage;